// mobile/screens/RecipeDetailScreen.js
import React, { useState, useEffect } from 'react';
import {
  View, 
  Text, 
  StyleSheet, 
  ScrollView, 
  TouchableOpacity,
  ActivityIndicator,
  Alert
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { getRecipeById, scaleRecipe, deleteRecipe } from '../services/api';
import { UI_CONFIG } from '../config';

export default function RecipeDetailScreen({ route, navigation }) {
  const { id } = route.params;

  const [recipe, setRecipe] = useState(null);
  const [loading, setLoading] = useState(true);
  const [servings, setServings] = useState(null);
  const [error, setError] = useState(null);
  const [scaling, setScaling] = useState(false);

  useEffect(() => {
    fetchRecipe();
  }, [id]);

  const fetchRecipe = async () => {
    try {
      setLoading(true);
      const recipeData = await getRecipeById(id);
      setRecipe(recipeData);
      setServings(recipeData.servings);
      setError(null);
    } catch (err) {
      console.error(err);
      setError('Failed to load recipe. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleScaleRecipe = async (newServings) => {
    if (newServings === recipe.servings) return;

    try {
      setScaling(true);
      const scaledRecipe = await scaleRecipe(id, newServings);
      setRecipe(scaledRecipe);
      setServings(newServings);
    } catch (err) {
      console.error(err);
      Alert.alert('Error', 'Failed to scale recipe. Please try again.');
    } finally {
      setScaling(false);
    }
  };

  const handleDeleteRecipe = () => {
    Alert.alert(
      'Delete Recipe',
      'Are you sure you want to delete this recipe?',
      [
        { text: 'Cancel', style: 'cancel' },
        { 
          text: 'Delete', 
          style: 'destructive',
          onPress: async () => {
            try {
              await deleteRecipe(id);
              navigation.goBack();
            } catch (err) {
              console.error(err);
              Alert.alert('Error', 'Failed to delete recipe. Please try again.');
            }
          }
        }
      ]
    );
  };

  const increaseServings = () => {
    handleScaleRecipe(servings + 1);
  };

  const decreaseServings = () => {
    if (servings > 1) {
      handleScaleRecipe(servings - 1);
    }
  };

  if (loading) {
    return (
      <View style={styles.centered}>
        <ActivityIndicator size="large" color={UI_CONFIG.PRIMARY_COLOR} />
      </View>
    );
  }

  if (error) {
    return (
      <View style={styles.centered}>
        <Text style={styles.errorText}>{error}</Text>
        <TouchableOpacity style={styles.retryButton} onPress={fetchRecipe}>
          <Text style={styles.retryText}>Try Again</Text>
        </TouchableOpacity>
      </View>
    );
  }

  if (!recipe) {
    return (
      <View style={styles.centered}>
        <Text style={styles.errorText}>Recipe not found</Text>
        <TouchableOpacity style={styles.retryButton} onPress={() => navigation.goBack()}>
          <Text style={styles.retryText}>Go Back</Text>
        </TouchableOpacity>
      </View>
    );
  }

  return (
    <ScrollView style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.title}>{recipe.title}</Text>

        {recipe.description && (
          <Text style={styles.description}>{recipe.description}</Text>
        )}

        <View style={styles.metaContainer}>
          <View style={styles.metaItem}>
            <Ionicons name="time-outline" size={18} color="#6c757d" />
            <Text style={styles.metaText}>
              {(recipe.prepTime || 0) + (recipe.cookTime || 0)} min
            </Text>
          </View>

          <View style={styles.servingsContainer}>
            <TouchableOpacity
              style={styles.servingButton}
              onPress={decreaseServings}
              disabled={servings <= 1 || scaling}
            >
              <Ionicons 
                name="remove" 
                size={18} 
                color={servings <= 1 ? "#ced4da" : "#6c757d"} 
              />
            </TouchableOpacity>

            <View style={styles.servingsTextContainer}>
              <Ionicons name="people-outline" size={18} color="#6c757d" />
              <Text style={styles.metaText}>
                {scaling ? (
                  <ActivityIndicator size="small" color={UI_CONFIG.PRIMARY_COLOR} />
                ) : (
                  `${servings} servings`
                )}
              </Text>
            </View>

            <TouchableOpacity
              style={styles.servingButton}
              onPress={increaseServings}
              disabled={scaling}
            >
              <Ionicons name="add" size={18} color="#6c757d" />
            </TouchableOpacity>
          </View>
        </View>
      </View>

      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Ingredients</Text>
        {recipe.ingredients.map((ingredient, index) => (
          <View key={index} style={styles.ingredient}>
            <Text style={styles.ingredientText}>
              {ingredient.amount} {ingredient.unit} {ingredient.name}
            </Text>
          </View>
        ))}
      </View>

      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Instructions</Text>
        {recipe.steps.map((step, index) => (
          <View key={index} style={styles.step}>
            <View style={styles.stepNumberContainer}>
              <Text style={styles.stepNumber}>{step.number}</Text>
            </View>
            <Text style={styles.stepText}>{step.instruction}</Text>
          </View>
        ))}
      </View>

      <View style={styles.actionButtons}>
        <TouchableOpacity
          style={[styles.actionButton, styles.editButton]}
          onPress={() => navigation.navigate('AddRecipe', { parsedRecipe: recipe })}
        >
          <Ionicons name="create-outline" size={20} color="#fff" style={styles.actionIcon} />
          <Text style={styles.actionText}>Edit</Text>
        </TouchableOpacity>

        <TouchableOpacity
          style={[styles.actionButton, styles.deleteButton]}
          onPress={handleDeleteRecipe}
        >
          <Ionicons name="trash-outline" size={20} color="#fff" style={styles.actionIcon} />
          <Text style={styles.actionText}>Delete</Text>
        </TouchableOpacity>
      </View>
    </ScrollView>
  );
}

